import java.lang.annotation.*;import java.lang.reflect.*;import java.util.*;
@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface NotBlank {}
@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface MaxLength { int value(); }
class SignupForm { @NotBlank @MaxLength(30) String username; @NotBlank @MaxLength(60) String email; SignupForm(String u,String e){username=u;email=e;} }
public class Main { static List<String> validate(Object obj)throws IllegalAccessException{List<String> errors=new ArrayList<>();for(Field f:obj.getClass().getDeclaredFields()){f.setAccessible(true);Object v=f.get(obj);if(f.isAnnotationPresent(NotBlank.class)&&(v==null||v.toString().isBlank()))errors.add(f.getName()+" must not be blank");MaxLength m=f.getAnnotation(MaxLength.class);if(m!=null&&v!=null&&v.toString().length()>m.value())errors.add(f.getName()+" exceeds "+m.value()+" characters");}return errors;}public static void main(String[] args)throws Exception{SignupForm form=new SignupForm("","verylongemailaddress@example.com");List<String> errors=validate(form);if(errors.isEmpty())System.out.println("Form is valid");else errors.forEach(System.out::println);} }
